    score = score.replace([np.inf, -np.inf], np.nan)
    valid = valid & score.notna() & vol.notna() & (vol > 0.01)
    if valid.sum() < 10:
        valid = last.notna() & np.isfinite(last) & (last > 0.0) & score.notna()
    if valid.sum() < 6:
